<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Accessor\SmtpOutboundConfigPortAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SmtpOutboundConfigPortAccessor trait.
 *
 * Covers null default, string/VO assignment via withPort,
 * getPort/port accessors, and isPortChanged with/without original.
 */
class SmtpOutboundConfigPortAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withPort creates a new instance with the Port set
     * from a string value, and getPort returns the primitive string.
     */
    public function testWithPortFromString(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigPortAccessorUnitTest();

        // Act
        $result = $holder->withPort(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isPort());
    }
    /**
     * Asserts that withport has access to the value object
     * from a string value, and getPort returns the primitive string.
     */
    public function testWithPortFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigPortAccessorUnitTest();

        // Act
        $result = $holder->withPort(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->port()->value());
    }
    public function testChangedPort(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigPortAccessorUnitTest()->withPort(true);
        $original = $holder->withPort(true);
        $same = $holder->withPort(true);
        $modified = $holder->withPort(false);

        // Act
        $withSame = $original->isPortChanged($same);
        $withDiferent = $original->isPortChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithSmtpOutboundConfigPortAccessorUnitTest
{
    use SmtpOutboundConfigPortAccessor;
}
